WITH unpacked AS (SELECT id, customer_id, created_at, ship_to, AGGREGATE(items, CAST(0 AS DOUBLE), (acc, i) -> acc + i.qty * i.price, acc -> ROUND(acc, 2)) AS cart_value, ARRAY_CONTAINS(MAP_KEYS(attributes), 'device') AS has_device, attributes['device'] AS device, SIZE(items) AS num_items, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code FROM carts WHERE customer_id IS NULL) SELECT CASE WHEN cart_value >= 1330 THEN 'PREMIUM' ELSE 'STANDARD' END AS cart_value_tier, customer_id, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes, COUNT(*) AS row_count, MAX(created_at) AS last_created_at FROM unpacked GROUP BY CASE WHEN cart_value >= 1330 THEN 'PREMIUM' ELSE 'STANDARD' END, customer_id;
